@@ -1 +1,59 @@
 export const pageReady = true;
+
+export function setMenuOpen(button, menu, open) {
+  menu.hidden = !open;
+  button.setAttribute("aria-expanded", String(open));
+  const label = button.querySelector?.(".sr-only");
+  if (label) label.textContent = open ? "Close navigation" : "Open navigation";
+}
+
+if (typeof document !== "undefined") {
+  const menuButton = document.querySelector(".menu-button");
+  const menu = document.querySelector("#site-nav");
+  const search = document.querySelector('input[type="search"]');
+  const filters = [...document.querySelectorAll(".filter")];
+  const cards = [...document.querySelectorAll(".project-card")];
+  const count = document.querySelector(".result-count");
+  const empty = document.querySelector(".empty-state");
+  const sort = document.querySelector("select");
+  const grid = document.querySelector(".projects");
+  let currentFilter = "all";
+
+  menuButton?.addEventListener("click", () => {
+    setMenuOpen(menuButton, menu, menuButton.getAttribute("aria-expanded") !== "true");
+  });
+
+  menu?.addEventListener("click", (event) => {
+    if (event.target.matches("a") && matchMedia("(max-width: 700px)").matches) setMenuOpen(menuButton, menu, false);
+  });
+
+  function updateProjects() {
+    const query = search.value.trim().toLocaleLowerCase();
+    let visible = 0;
+    cards.forEach((card) => {
+      const matchesFilter = currentFilter === "all" || card.dataset.status === currentFilter;
+      const matchesQuery = card.dataset.name.toLocaleLowerCase().includes(query) || card.textContent.toLocaleLowerCase().includes(query);
+      card.hidden = !(matchesFilter && matchesQuery);
+      if (!card.hidden) visible += 1;
+    });
+    count.textContent = `${visible} project${visible === 1 ? "" : "s"}`;
+    empty.hidden = visible !== 0;
+  }
+
+  search?.addEventListener("input", updateProjects);
+  filters.forEach((button) => button.addEventListener("click", () => {
+    currentFilter = button.dataset.filter;
+    filters.forEach((item) => {
+      const selected = item === button;
+      item.classList.toggle("active", selected);
+      item.setAttribute("aria-pressed", String(selected));
+    });
+    updateProjects();
+  }));
+
+  sort?.addEventListener("change", () => {
+    const ordered = [...cards];
+    if (sort.value === "name") ordered.sort((a, b) => a.dataset.name.localeCompare(b.dataset.name));
+    ordered.forEach((card) => grid.append(card));
+  });
+}
