diff --git a/styles.css b/styles.css
index 6dbc6af..b6e64ec 100644
--- a/styles.css
+++ b/styles.css
@@ -1,3 +1,68 @@
-body { margin: 0; font-family: system-ui, sans-serif; }
-main, header { padding: 1rem; }
-.projects { display: block; }
+:root { color-scheme: light; --ink: #17201d; --muted: #66716c; --line: #dcded8; --paper: #f5f3ed; --card: #fffefa; --green: #174d3d; --focus: #236b55; }
+* { box-sizing: border-box; }
+body { margin: 0; min-width: 320px; background: var(--paper); color: var(--ink); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
+button, input, select { font: inherit; }
+button, a, input, select { -webkit-tap-highlight-color: transparent; }
+button { color: inherit; }
+:focus-visible { outline: 3px solid #7fb7a5; outline-offset: 3px; }
+.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
+.skip-link { position: fixed; z-index: 20; top: .5rem; left: .5rem; padding: .7rem 1rem; background: var(--ink); color: white; transform: translateY(-150%); }
+.skip-link:focus { transform: none; }
+.topbar { min-height: 72px; padding: 0 clamp(1rem, 4vw, 4.5rem); border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 2rem; background: rgba(255,254,250,.88); backdrop-filter: blur(14px); position: sticky; top: 0; z-index: 10; }
+.brand { color: var(--ink); text-decoration: none; display: inline-flex; align-items: center; gap: .7rem; font-family: Georgia, serif; font-size: 1.08rem; font-weight: 700; }
+.brand-mark { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--green); color: white; font-family: ui-sans-serif, system-ui; font-size: .68rem; letter-spacing: -.05em; }
+.site-nav { display: flex; gap: .25rem; align-self: stretch; align-items: center; }
+.site-nav a { padding: .55rem .8rem; border-radius: 8px; color: var(--muted); font-size: .9rem; font-weight: 600; text-decoration: none; }
+.site-nav a:hover, .site-nav a.active { background: #e8ece7; color: var(--ink); }
+.avatar { margin-left: auto; width: 36px; height: 36px; border: 0; border-radius: 50%; background: #d9b59e; font-size: .72rem; font-weight: 800; cursor: pointer; }
+.menu-button { display: none; margin-left: auto; width: 42px; height: 42px; padding: 10px; border: 1px solid var(--line); border-radius: 10px; background: transparent; }
+.menu-button span:not(.sr-only) { display: block; height: 2px; margin: 4px 0; background: currentColor; border-radius: 2px; }
+main { width: min(1400px, 100%); margin: 0 auto; padding: clamp(2.4rem, 5vw, 5.5rem) clamp(1rem, 4vw, 4.5rem) 5rem; }
+.eyebrow { margin: 0 0 .85rem; color: var(--green); font-size: .72rem; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }
+.hero-row { display: flex; align-items: end; justify-content: space-between; gap: 2rem; }
+h1 { margin: 0; font-family: Georgia, Cambria, serif; font-size: clamp(2.6rem, 6vw, 4.8rem); font-weight: 500; line-height: .95; letter-spacing: -.045em; }
