+.primary-button { min-height: 46px; padding: .75rem 1.05rem; border: 0; border-radius: 10px; background: var(--green); color: white; font-weight: 750; box-shadow: 0 5px 16px #174d3d24; cursor: pointer; white-space: nowrap; }
+.primary-button:hover { background: #0f3d30; transform: translateY(-1px); }
+.browser { margin-top: clamp(2.5rem, 6vw, 4.8rem); }
+.toolbar { display: grid; grid-template-columns: minmax(220px, 1fr) auto auto; align-items: center; gap: 1rem; padding-bottom: 1.25rem; border-bottom: 1px solid var(--line); }
+.search { position: relative; display: block; max-width: 360px; }
