+.search input { width: 100%; height: 44px; padding: 0 1rem 0 2.6rem; border: 1px solid var(--line); border-radius: 10px; background: var(--card); color: var(--ink); }
+.search input::placeholder { color: #89918d; }
+.filters { display: flex; gap: .2rem; padding: .2rem; background: #e9e9e3; border-radius: 10px; }
+.filter { min-height: 36px; padding: .4rem .7rem; border: 0; border-radius: 8px; background: transparent; color: var(--muted); font-size: .82rem; font-weight: 700; cursor: pointer; }
+.filter span { margin-left: .25rem; opacity: .65; }
