+.sort { display: flex; align-items: center; gap: .5rem; color: var(--muted); font-size: .78rem; font-weight: 700; }
+.sort select { height: 38px; padding: 0 2rem 0 .7rem; border: 1px solid var(--line); border-radius: 8px; background: var(--card); color: var(--ink); }
+.result-count { margin: 1.25rem 0 .8rem; color: var(--muted); font-size: .78rem; font-weight: 650; }
+.projects { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
+.project-card { min-height: 300px; padding: 1.25rem; border: 1px solid var(--line); border-radius: 15px; background: var(--card); display: flex; flex-direction: column; justify-content: space-between; box-shadow: 0 1px 0 #17201d08; transition: transform .18s, box-shadow .18s, border-color .18s; }
+.project-card:hover { transform: translateY(-3px); border-color: #c5c9c1; box-shadow: 0 12px 30px #2431290d; }
+.card-top { display: flex; justify-content: space-between; align-items: start; }
+.project-icon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 13px; font-family: Georgia, serif; font-size: 1.2rem; font-weight: 700; }
+.coral { background: #f5d9cc; color: #843d27; }.blue { background: #d7e7ee; color: #235a6f; }.green { background: #dbe8d5; color: #396037; }.violet { background: #e4deef; color: #564274; }.gold { background: #efe2bd; color: #725b1f; }.teal { background: #cfe8e2; color: #285f54; }
+.more { min-width: 40px; min-height: 40px; border: 0; border-radius: 8px; background: transparent; color: var(--muted); letter-spacing: .08em; cursor: pointer; }
+.more:hover { background: #f0f0ea; }
+.status { display: inline-block; margin: 2.2rem 0 .65rem; font-size: .66rem; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
+.active-status { color: #247058; }.planning-status { color: #8b6820; }
+.project-card h2 { margin: 0; font-family: Georgia, serif; font-size: 1.7rem; font-weight: 600; letter-spacing: -.02em; }
+.project-card p { margin: .55rem 0 1.7rem; color: var(--muted); font-size: .88rem; line-height: 1.55; }
+.project-card footer { padding-top: 1rem; border-top: 1px solid #ecece6; display: flex; justify-content: space-between; align-items: center; gap: .5rem; }
+.project-card time { color: #7a837e; font-size: .72rem; }
+.people { display: flex; }
+.people span { display: grid; place-items: center; width: 27px; height: 27px; margin-left: -5px; border: 2px solid var(--card); border-radius: 50%; background: #dfe2dc; color: #4f5b55; font-size: .54rem; font-weight: 800; }
+.people span:first-child { margin-left: 0; }
+.empty-state { padding: 4rem 1rem; text-align: center; color: var(--muted); }
+.empty-state > span { font-size: 2rem; }.empty-state h2 { color: var(--ink); margin-bottom: .4rem; }.empty-state p { margin: 0; }
+[hidden] { display: none !important; }
+@media (max-width: 900px) { .projects { grid-template-columns: repeat(2, 1fr); } .toolbar { grid-template-columns: 1fr auto; } .search { max-width: none; } .sort { display: none; } .filters { grid-column: 1 / -1; justify-self: start; } }
+@media (min-width: 701px) { .site-nav[hidden] { display: flex !important; } }
+@media (max-width: 700px) {
+  .topbar { min-height: 64px; gap: .5rem; } .menu-button { display: block; } .avatar { margin-left: .25rem; }
+  .site-nav { position: absolute; top: calc(100% + 1px); left: 0; right: 0; padding: .7rem 1rem 1rem; background: var(--card); border-bottom: 1px solid var(--line); box-shadow: 0 12px 20px #17201d12; flex-direction: column; align-items: stretch; }
+  .site-nav a { padding: .8rem; } main { padding-top: 2.6rem; } .hero-row { align-items: stretch; flex-direction: column; gap: 1.6rem; } .primary-button { align-self: flex-start; }
+  .projects { grid-template-columns: 1fr; } .project-card { min-height: 280px; } .toolbar { grid-template-columns: 1fr; } .filters { grid-column: auto; width: 100%; overflow-x: auto; } .filter { flex: 1; }
+}
+@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }
